// Get the AI response and format it for the widget
const aiOutput = $input.first().json;

// The AI Agent outputs in 'output' field
const response = aiOutput.output || aiOutput.text || 'Sorry, I could not process that.';

// Get session ID from original webhook
const sessionId = $('Webhook').first().json.body.sessionId || '';

return {
  json: {
    success: true,
    response: response,
    sessionId: sessionId
  }
};
